                        listOf("Group" to "குழு", "Example" to "எடுத்துக்காட்டு", "Key features" to "முக்கியப் பண்புகள்", "Modern position" to "நவீன இடம்"),
                        listOf(
                            listOf("Archiannelida" to "ஆர்க்கியனெலிடா", "Polygordius, Protodrilus" to "பாலிகார்டியஸ், புரோட்டோட்ரிலஸ்", "Small, simple, little external segmentation, interstitial" to "சிறியவை, எளியவை, குறைந்த வெளிக் கண்டமாக்கம், இடைவெளி வாழ்", "Annelida (polychaete lines)" to "அனெலிடா (பாலிகீட்டுக் கிளைகள்)"),
                            listOf("Echiuroidea" to "எக்கியூராய்டியா", "Echiurus, Bonellia, Urechis" to "எக்கியூரஸ், பொனெல்லியா, யூரெசிஸ்", "Unsegmented trunk, non-retractile proboscis, one pair of chaetae" to "கண்டமற்ற உடற்பகுதி, உள்ளிழுக்க இயலாத துதிக்கை, ஒரு இணை சீட்டாக்கள்", "Annelida (segments lost)" to "அனெலிடா (கண்டங்கள் இழப்பு)"),
                            listOf("Sipunculoidea" to "சிப்புங்குலாய்டியா", "Sipunculus, Phascolosoma" to "சிப்புங்குலஸ், ஃபாஸ்கோலோசோமா", "Unsegmented, retractable introvert, U-shaped gut, haemerythrin" to "கண்டமற்றது, உள்ளிழுக்கும் இன்ட்ரோவெர்ட், U வடிவ குடல், ஹீமெரித்ரின்", "Probably Annelida" to "ஒருவேளை அனெலிடா"),
                            listOf("Priapulida" to "பிரையாப்புலிடா", "Priapulus" to "பிரையாப்புலஸ்", "Introvert with scalids, moulting cuticle, no trochophore" to "ஸ்கேலிடுகளுடன் இன்ட்ரோவெர்ட், உரிக்கும் தோல், ட்ரோக்கோஃபோர் இல்லை", "Ecdysozoa, not Annelida" to "எக்டைசோசோவா; அனெலிடா அல்ல"),
                            listOf("Myzostomaria" to "மைசோஸ்டோமேரியா", "Myzostoma" to "மைசோஸ்டோமா", "Flat disc, five pairs of hooked appendages, on crinoids" to "தட்டையான வட்டு, கொக்கி உறுப்புகள் ஐந்து இணை, கிரினாய்டுகளில்", "Annelida (modified)" to "அனெலிடா (மாற்றமடைந்தவை)"),
